CREATE TABLE "HealthCareProgram" (id TEXT PRIMARY KEY,code TEXT NOT NULL UNIQUE,name TEXT NOT NULL,"isActive" BOOLEAN NOT NULL DEFAULT true,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE "HealthCareProgramEnrollment" (id TEXT PRIMARY KEY,"programId" TEXT NOT NULL REFERENCES "HealthCareProgram"(id) ON DELETE RESTRICT ON UPDATE CASCADE,"patientId" TEXT NOT NULL REFERENCES "Patient"(id) ON DELETE RESTRICT ON UPDATE CASCADE,"unitId" TEXT NOT NULL REFERENCES "HealthUnit"(id) ON DELETE RESTRICT ON UPDATE CASCADE,"startsAt" TIMESTAMP(3) NOT NULL,"endsAt" TIMESTAMP(3),reason TEXT NOT NULL,"closureReason" TEXT,"createdByUsuarioId" TEXT NOT NULL,"closedByUsuarioId" TEXT,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX "HealthCareProgramEnrollment_programId_patientId_startsAt_idx" ON "HealthCareProgramEnrollment"("programId","patientId","startsAt");
